// Copies xterm.css out of the installed package into a Lit-importable module.
// The panel renders in shadow DOM, so the stylesheet has to travel with the
// component; committing the generated file keeps the bundle-drift check honest.
import { readFileSync, writeFileSync, mkdirSync } from "node:fs";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const here = dirname(fileURLToPath(import.meta.url));
const source = resolve(here, "../node_modules/@xterm/xterm/css/xterm.css");
const target = resolve(here, "../src/generated/xterm-css.ts");
const css = readFileSync(source, "utf8").replace(/`/g, "\`").replace(/\$\{/g, "\${");
mkdirSync(dirname(target), { recursive: true });
writeFileSync(
  target,
  `// Generated by scripts/gen-xterm-css.mjs from @xterm/xterm/css/xterm.css; do not edit.\nexport const xtermCss = \`${css}\`;\n`
);
